// Validate Request
// Bubble's free plan cannot expose an API, so n8n has no way to read from
// Bubble. Bubble therefore sends everything the summary needs in the webhook
// body, and this node is the gate that checks it before any AI call is made.
// It also normalises the values: Bubble sends numbers as text (an empty
// number becomes "", which keeps the JSON valid for books in production).

const body = $('Royalty Summary Webhook').first().json.body ?? {};
const BUBBLE_ID = /^\d+x\d+$/; // Bubble unique ids look like 1718123456789x123456789012345678

const errors = [];
const text = (v) => (v === undefined || v === null ? '' : String(v).trim());
const number = (v) => {
  const s = text(v).replace(/,/g, '');
  if (s === '') return null;
  const n = Number(s);
  if (!Number.isFinite(n)) errors.push(`"${v}" is not a number`);
  return Number.isFinite(n) ? n : null;
};

let books = body.books;
if (typeof books === 'string') {
  try {
    books = JSON.parse(books);
  } catch {
    errors.push('books is not valid JSON');
    books = [];
  }
}
if (!Array.isArray(books)) {
  errors.push('books must be a list');
  books = [];
}

const author = body.author ?? {};
const logId = text(body.log_id);
const triggerType = text(body.trigger_type) || 'Single';

if (!BUBBLE_ID.test(logId)) errors.push('log_id must be a Bubble unique id');
if (!BUBBLE_ID.test(text(author.id))) errors.push('author.id must be a Bubble unique id');
if (!text(author.name)) errors.push('author.name is required');
if (!['Single', 'Bulk'].includes(triggerType)) errors.push('trigger_type must be "Single" or "Bulk"');

const normalisedBooks = books.map((b, i) => {
  if (!text(b?.title)) errors.push(`books[${i}].title is required`);
  if (!text(b?.status)) errors.push(`books[${i}].status is required`);
  const platforms = Array.isArray(b?.available_on)
    ? b.available_on
    : text(b?.available_on).split(',').map((p) => p.trim()).filter(Boolean);
  return {
    title: text(b?.title),
    genre: text(b?.genre),
    status: text(b?.status),
    publication_date: text(b?.publication_date),
    mrp: number(b?.mrp),
    royalty_per_copy: number(b?.royalty_per_copy),
    copies_sold: number(b?.copies_sold) ?? 0,
    royalty_earned: number(b?.royalty_earned) ?? 0,
    royalty_paid: number(b?.royalty_paid) ?? 0,
    royalty_pending: number(b?.royalty_pending) ?? 0,
    last_payout_date: text(b?.last_payout_date),
    available_on: platforms,
  };
});

// Replay protection: the same log id is never processed twice. Workflow
// static data only persists for executions of the active (production)
// workflow, which is the only place this matters.
let replay = false;
if (errors.length === 0) {
  const store = $getWorkflowStaticData('global');
  const now = Date.now();
  store.seenLogs = store.seenLogs ?? {};
  for (const [id, at] of Object.entries(store.seenLogs)) {
    if (now - at > 24 * 60 * 60 * 1000) delete store.seenLogs[id];
  }
  replay = Boolean(store.seenLogs[logId]);
  if (!replay) store.seenLogs[logId] = now;
}

const valid = errors.length === 0 && !replay;

return [{
  json: {
    valid,
    response_code: valid ? 200 : replay ? 409 : 400,
    status: valid ? '' : replay ? 'Skipped' : 'Failed',
    error_stage: valid ? '' : replay ? 'replay' : 'invalid_payload',
    error_message: replay ? `Log ${logId} was already processed` : errors.slice(0, 10).join('; '),
    log_id: logId,
    trigger_type: triggerType,
    requested_by: text(body.requested_by).slice(0, 200),
    as_of_date: text(body.as_of_date),
    author: { id: text(author.id), name: text(author.name), email: text(author.email) },
    books: normalisedBooks,
  },
}];

// Build Royalty Facts
// Turns the author and book data Bubble sent into one pre-computed fact sheet.
// Every amount, date and status the email mentions is worked out here,
// deterministically, so the model only writes prose around values it is
// given and never does arithmetic or date maths of its own.

const request = $('Validate Request').first().json;
const cfg = $('Config').first().json;
const author = request.author;
const books = request.books;

// Policy values mirror Bubble's AppSettings row (90 / 1,000 / 45) so the
// badges in Bubble and this email agree. as_of_date comes from AppSettings via
// the payload, so a demo date set in Bubble applies here too.
const OVERDUE_AFTER_DAYS = Number(cfg.overdue_after_days ?? 90);
const MIN_PAYOUT = Number(cfg.min_payout_threshold ?? 1000);
const PAYOUT_WINDOW_DAYS = Number(cfg.payout_window_days ?? 45);
const ESCALATION_HOURS = 48;

const DAY_MS = 24 * 60 * 60 * 1000;
const IST_OFFSET_MS = 330 * 60 * 1000;
const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July',
  'August', 'September', 'October', 'November', 'December'];
const PUBLISHED = 'Published & Live';
const PRODUCTION_STAGES = ['Manuscript Received', 'Editing', 'Cover Design', 'Typesetting',
  'Proofreading', 'ISBN Assignment', 'Printing', 'Distribution Setup', PUBLISHED];

// Every date is reduced to an IST calendar day (as a UTC-midnight timestamp)
// before comparing. Bubble sends dates already formatted in IST as
// yyyy-mm-dd, which is taken as that calendar day directly; anything else
// (an instant, or another unambiguous format) is parsed and shifted to IST.
function istDay(value) {
  if (value === undefined || value === null || value === '') return null;
  const ymd = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(value));
  if (ymd) return Date.UTC(Number(ymd[1]), Number(ymd[2]) - 1, Number(ymd[3]));
  const t = typeof value === 'number' ? value : Date.parse(value);
  if (Number.isNaN(t)) return null;
  const d = new Date(t + IST_OFFSET_MS);
  return Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate());
}

const formatDate = (day) => {
  const d = new Date(day);
  return `${d.getUTCDate()} ${MONTHS[d.getUTCMonth()]} ${d.getUTCFullYear()}`;
};
const isoDate = (day) => new Date(day).toISOString().slice(0, 10);
const toNumber = (v) => (Number.isFinite(Number(v)) ? Number(v) : 0);

// Indian digit grouping (1,23,456) without relying on the runtime's ICU data.
function groupIndian(n) {
  const [int, dec] = Math.abs(n).toFixed(2).split('.');
  const last3 = int.slice(-3);
  const rest = int.slice(0, -3);
  const grouped = rest ? `${rest.replace(/\B(?=(\d{2})+(?!\d))/g, ',')},${last3}` : last3;
  return `${n < 0 ? '-' : ''}${grouped}${dec === '00' ? '' : `.${dec}`}`;
}
const inr = (n) => `₹${groupIndian(n)}`;

// Royalties are calculated per calendar quarter and paid within
// PAYOUT_WINDOW_DAYS of the quarter ending. Returns the first payout deadline
// on or after `fromDay`, plus the quarter it covers.
function nextPayoutCycle(fromDay) {
  const year = new Date(fromDay).getUTCFullYear();
  for (let y = year - 1; y <= year + 1; y++) {
    for (const lastMonth of [2, 5, 8, 11]) {
      const quarterEnd = Date.UTC(y, lastMonth + 1, 0);
      const deadline = quarterEnd + PAYOUT_WINDOW_DAYS * DAY_MS;
      if (deadline >= fromDay) {
        const quarterStart = Date.UTC(y, lastMonth - 2, 1);
        return {
          deadline,
          quarterLabel: `${MONTHS[new Date(quarterStart).getUTCMonth()]} to ${MONTHS[lastMonth]} ${y}`,
          quarterEnd,
        };
      }
    }
  }
  throw new Error('Could not determine the next payout cycle');
}

const asOfDay = istDay(request.as_of_date) ?? istDay(Date.now());
const cycle = nextPayoutCycle(asOfDay);

const totalPending = books.reduce((sum, b) => sum + toNumber(b.royalty_pending), 0);
const belowThreshold = totalPending > 0 && totalPending < MIN_PAYOUT;

const published = [];
const inProduction = [];
const warnings = [];

const sorted = [...books].sort((a, b) =>
  (istDay(a.publication_date) ?? Infinity) - (istDay(b.publication_date) ?? Infinity)
  || String(a.title).localeCompare(String(b.title)));

for (const book of sorted) {
  const status = String(book.status ?? '');

  if (status !== PUBLISHED) {
    const stage = status.replace(/^In Production\s*-\s*/i, '').trim();
    const index = PRODUCTION_STAGES.indexOf(stage);
    inProduction.push({
      title: book.title,
      genre: book.genre ?? '',
      current_stage: stage || status || 'In production',
      stage_position: index >= 0 ? `stage ${index + 1} of ${PRODUCTION_STAGES.length}` : '',
      next_stage: index >= 0 && index < PRODUCTION_STAGES.length - 1 ? PRODUCTION_STAGES[index + 1] : '',
    });
    continue;
  }

  const earned = toNumber(book.royalty_earned);
  const paid = toNumber(book.royalty_paid);
  const pending = toNumber(book.royalty_pending);
  if (Math.abs(earned - paid - pending) > 0.01) {
    warnings.push(`${book.title}: earned (${earned}) is not paid (${paid}) + pending (${pending})`);
  }

  // The overdue clock starts at the last payout, or at publication if the
  // book has never been paid out.
  const lastPayoutDay = istDay(book.last_payout_date);
  const clockStart = lastPayoutDay ?? istDay(book.publication_date);
  const daysWaiting = clockStart === null ? null : Math.floor((asOfDay - clockStart) / DAY_MS);

  let payoutStatus;
  if (pending <= 0) payoutStatus = earned > 0 ? 'paid_up' : 'no_earnings_yet';
  else if (belowThreshold) payoutStatus = 'below_threshold';
  else if (daysWaiting !== null && daysWaiting > OVERDUE_AFTER_DAYS) payoutStatus = 'overdue';
  else payoutStatus = 'pending_on_schedule';

  published.push({
    title: book.title,
    genre: book.genre ?? '',
    published_on: istDay(book.publication_date) === null ? '' : formatDate(istDay(book.publication_date)),
    available_on: Array.isArray(book.available_on) ? book.available_on : [],
    copies_sold: groupIndian(toNumber(book.copies_sold)),
    royalty_per_copy: inr(toNumber(book.royalty_per_copy)),
    royalty_earned: inr(earned),
    royalty_paid: inr(paid),
    royalty_pending: inr(pending),
    last_payout: lastPayoutDay === null ? 'No payout yet' : formatDate(lastPayoutDay),
    payout_status: payoutStatus,
    _days_waiting: daysWaiting,
    _amounts: [earned, paid, pending, toNumber(book.royalty_per_copy), toNumber(book.mrp)],
  });
}

const sum = (field) => books.reduce((acc, b) => acc + toNumber(b[field]), 0);
const totals = {
  earned: sum('royalty_earned'),
  paid: sum('royalty_paid'),
  pending: totalPending,
  copies: sum('copies_sold'),
};

const titlesWith = (status) => published.filter((b) => b.payout_status === status).map((b) => b.title);
const overdueTitles = titlesWith('overdue');
const onScheduleTitles = titlesWith('pending_on_schedule');

let scenario;
if (published.length === 0) scenario = 'no_published_books';
else if (totals.pending <= 0) scenario = 'all_paid';
else if (belowThreshold) scenario = 'below_threshold';
else if (overdueTitles.length) scenario = 'overdue';
else scenario = 'pending_on_schedule';

const firstName = String(author.name ?? '').trim().split(/\s+/)[0] || 'there';

// Only what the email needs goes to the model: no email address, phone, ISBN
// or internal ids (data minimisation, and fewer tokens).
const aiFacts = {
  todays_date: formatDate(asOfDay),
  author_first_name: firstName,
  author_full_name: author.name ?? '',
  published_books: published.map(({ _days_waiting, _amounts, ...b }) => b),
  books_in_production: inProduction,
  totals: {
    copies_sold: groupIndian(totals.copies),
    royalty_earned: inr(totals.earned),
    royalty_paid: inr(totals.paid),
    royalty_pending: inr(totals.pending),
  },
  payout: {
    scenario,
    overdue_books: overdueTitles,
    on_schedule_books: onScheduleTitles,
    next_payout_deadline: formatDate(cycle.deadline),
    quarter_covered_by_next_payout: cycle.quarterLabel,
    minimum_payout: inr(MIN_PAYOUT),
    escalation_window: `${ESCALATION_HOURS} hours`,
  },
};

// Every rupee amount the email is allowed to contain. validate-ai-output.js
// rejects the email if the model writes any other amount.
const allowedAmounts = [...new Set([
  totals.earned, totals.paid, totals.pending, MIN_PAYOUT,
  ...published.flatMap((b) => b._amounts),
])];

return [{
  json: {
    log_id: request.log_id,
    author_id: author.id,
    as_of: isoDate(asOfDay),
    scenario,
    ai_facts: aiFacts,
    policy: { overdue_after_days: OVERDUE_AFTER_DAYS, min_payout: MIN_PAYOUT, payout_window_days: PAYOUT_WINDOW_DAYS },
    guardrails: {
      allowed_amounts: allowedAmounts,
      required_titles: [...published, ...inProduction].map((b) => b.title),
      first_name: firstName,
    },
    delivery: { name: author.name ?? '', email: author.email ?? '' },
    book_statuses: published.map((b) => ({ title: b.title, status: b.payout_status, days_waiting: b._days_waiting })),
    data_warnings: warnings,
  },
}];

// Build AI Request
// Assembles the Gemini generateContent request.
//
// Prompt strategy:
//  - The system prompt holds only stable content: role, the royalty policy
//    slice of the Knowledge Base, tone rules and hard output rules.
//  - The user message holds a numbered "must cover" checklist built from this
//    author's situation, plus the FACTS JSON. Only instructions that apply are
//    included (an all-paid author never sees the overdue rules), which keeps
//    the prompt short and stops the model from hedging across scenarios.
//  - The production-stage part of the Knowledge Base is only sent when the
//    author actually has a book in production.

const cfg = $('Config').first().json;
const { ai_facts: facts, policy } = $('Build Royalty Facts').first().json;
const payout = facts.payout;

const TONE = `
- Empathetic and professional. Authors are partners, not customers to be managed.
- Acknowledge the author's situation before moving to details.
- Be specific: real numbers, dates and statuses instead of vague reassurance.
- If something is BookLeaf's fault (for example a delayed royalty), own it directly. No deflection.
- If something needs escalation, give a concrete timeline, never an open-ended promise.
- End with a clear next step for the author and/or the BookLeaf team.
`.trim();

const SYSTEM_PROMPT = `
You write royalty summary emails from BookLeaf Publishing to its authors.
BookLeaf is a self-publishing company in India and the US. It handles cover design, typesetting, ISBN assignment, printing, distribution and royalty management for its authors.

Royalty policy (state it accurately and never contradict it):
- Royalties are calculated every calendar quarter and paid within ${policy.payout_window_days} days of the quarter ending.
- The minimum payout is ${payout.minimum_payout}. A smaller balance rolls over to the next quarter.
- Payouts are made by bank transfer to the bank account linked in the author's BookLeaf dashboard.
- The dashboard shows a per-platform breakdown of sales and royalties.

Tone:
${TONE}

Hard rules:
1. Use only the names, titles, amounts, dates and statuses in FACTS. Copy every amount and date exactly as written there. Never calculate, round, convert or invent a number or a date.
2. Never ask the author to email bank details or other personal information. Point them to the dashboard instead.
3. Plain text only: no markdown, bold, headings or tables. Short paragraphs, and "- " bullets for the list of books.
4. The body is 170 to 320 words.
5. Start the body with "Dear ${facts.author_first_name}," and end it with exactly these two lines:
Warm regards,
Team BookLeaf
6. Return JSON with "subject" (under 80 characters, says it is a royalty summary) and "body".
`.trim();

// Quoted and joined with "and" so titles that contain punctuation stay readable.
const titleList = (titles) => {
  const quoted = titles.map((t) => `"${t}"`);
  return quoted.length > 1 ? `${quoted.slice(0, -1).join(', ')} and ${quoted.at(-1)}` : quoted[0];
};

const tasks = [];
if (facts.published_books.length) {
  tasks.push('For every book in published_books, one bullet with the title, copies sold, royalty earned, royalty paid, royalty pending and the last payout date (or that no payout has been made yet).');
  tasks.push('A clear totals line across all books: total earned, total paid and total pending, exactly as in totals.');
}

switch (payout.scenario) {
  case 'all_paid':
    tasks.push('Every royalty earned so far has been paid. Acknowledge this warmly and thank the author; there is no pending amount to explain.');
    break;
  case 'below_threshold':
    tasks.push(`The total pending balance (${facts.totals.royalty_pending}) is below the ${payout.minimum_payout} minimum payout, so it rolls over to the next quarter and is paid once the balance reaches ${payout.minimum_payout}. Explain this reassuringly: nothing is wrong and nothing is lost.`);
    break;
  case 'no_published_books':
    tasks.push('No book is published yet, so there are no royalties to report. Say that royalties start once a book is live.');
    break;
  default:
    if (payout.overdue_books.length) {
      tasks.push(`Pending royalties for ${titleList(payout.overdue_books)} are past BookLeaf's normal quarterly payout schedule. Say this plainly, apologise once and take ownership without blaming banks, platforms or the author. Say the BookLeaf finance team is reviewing it now and will update the author within ${payout.escalation_window}, and ask them to check that the bank account linked in their dashboard is current so nothing holds the payment up.`);
    }
    if (payout.on_schedule_books.length) {
      tasks.push(`Pending royalties for ${titleList(payout.on_schedule_books)} are within the normal cycle. Tell the author to expect them in the payout due by ${payout.next_payout_deadline}, which covers ${payout.quarter_covered_by_next_payout}.`);
    }
}

if (facts.books_in_production.length) {
  tasks.push('For each book in books_in_production, a short, encouraging status update: name its current stage and stage_position, mention the next stage, and say the author will get an email as it moves through each stage. Do not give or guess a publication date. If a book is at Cover Design, you may say the team will reach out if they need the author\'s input on the cover, framed as working together.');
}

tasks.push('Close with one clear next step for the author (for example, the per-platform breakdown in their dashboard, or simply replying to this email with questions) before the sign-off.');

const productionContext = facts.books_in_production.length
  ? '\nBookLeaf production stages, in order: Manuscript Received, Editing (if opted), Cover Design, Typesetting, Proofreading, ISBN Assignment, Printing, Distribution Setup, Published & Live.\n'
  : '';

const userMessage = `
Write the royalty summary email for this author. Today's date is ${facts.todays_date}.
${productionContext}
The email must cover, in this order:
${tasks.map((t, i) => `${i + 1}. ${t}`).join('\n')}

FACTS:
${JSON.stringify(facts, null, 2)}
`.trim();

const generationConfig = {
  temperature: 0.4,
  maxOutputTokens: 2048,
  responseMimeType: 'application/json',
  responseSchema: {
    type: 'OBJECT',
    properties: {
      subject: { type: 'STRING' },
      body: { type: 'STRING' },
    },
    required: ['subject', 'body'],
  },
};
// Thinking adds cost and latency without helping a templated email. Leave the
// Config value empty if a model does not accept this setting.
if (cfg.gemini_thinking_level) {
  generationConfig.thinkingConfig = { thinkingLevel: cfg.gemini_thinking_level };
}

return [{
  json: {
    model: cfg.gemini_model,
    gemini_request: {
      systemInstruction: { parts: [{ text: SYSTEM_PROMPT }] },
      contents: [{ role: 'user', parts: [{ text: userMessage }] }],
      generationConfig,
    },
  },
}];

// Validate AI Output
// Guardrails between the model and the author's inbox. The email is only
// accepted if it parses, is complete, greets the right person, mentions every
// book, and contains no rupee amount that is not in the source data.
// This node never throws: it reports problems so the IF node after it can
// route a bad generation to the "Failed" callback with a readable reason.

const cfg = $('Config').first().json;
const facts = $('Build Royalty Facts').first().json;
const model = $('Build AI Request').first().json.model;
const response = $input.first().json;

const problems = [];
let subject = '';
let body = '';

const candidate = response.candidates?.[0];
if (response.promptFeedback?.blockReason) problems.push(`Prompt blocked by the model: ${response.promptFeedback.blockReason}`);
if (!candidate) problems.push('The model returned no candidate');
if (candidate?.finishReason && candidate.finishReason !== 'STOP') {
  problems.push(`Generation did not finish normally (finishReason: ${candidate.finishReason})`);
}

const text = (candidate?.content?.parts ?? [])
  .filter((part) => !part.thought && typeof part.text === 'string')
  .map((part) => part.text)
  .join('')
  .trim();

let parsed = null;
if (text) {
  try {
    parsed = JSON.parse(text.replace(/^```(?:json)?\s*|\s*```$/g, ''));
  } catch {
    problems.push('The model output was not valid JSON');
  }
}

if (parsed) {
  subject = String(parsed.subject ?? '').trim();
  body = String(parsed.body ?? '').replace(/\r\n/g, '\n').trim();

  if (subject.length < 5 || subject.length > 150) problems.push('Subject is missing or an odd length');
  if (body.length < 300) problems.push('Body is missing or too short');
  if (body.length > 6000) problems.push('Body is unexpectedly long');

  const normalise = (s) => s.toLowerCase().replace(/[‘’`]/g, "'");
  const bodyNorm = normalise(body);

  if (!bodyNorm.includes(normalise(facts.guardrails.first_name))) problems.push('Greeting does not use the author\'s name');

  const missing = facts.guardrails.required_titles.filter((t) => !bodyNorm.includes(normalise(t)));
  if (missing.length) problems.push(`Books not mentioned: ${missing.join(', ')}`);

  // Any amount written as ₹, Rs or INR must be one of the source figures.
  const allowed = new Set(facts.guardrails.allowed_amounts.map(Number));
  const amountPattern = /(?:₹|\brs\.?|\binr)\s*([0-9][0-9,]*(?:\.[0-9]+)?)/gi;
  const invented = [...body.matchAll(amountPattern)]
    .map((m) => m[1])
    .filter((raw) => !allowed.has(Number(raw.replace(/,/g, ''))));
  if (invented.length) problems.push(`Amounts not in the source data: ${[...new Set(invented)].join(', ')}`);

  if (/\[[^\]]*\]|\{\{|<[a-z _]+>/i.test(body)) problems.push('Body contains an unfilled placeholder');
}

// Delivery decision. The dataset uses real-looking addresses on a real mail
// provider's domain, so "live" sending is opt-in and the default sends every
// summary to a test inbox instead.
const mode = String(cfg.email_mode ?? 'off').toLowerCase();
let recipient = '';
let skipReason = '';
if (mode === 'live') {
  recipient = facts.delivery.email;
  if (!recipient) skipReason = 'Author has no email address';
} else if (mode === 'override') {
  recipient = String(cfg.email_override_recipient ?? '').trim();
  if (!recipient) skipReason = 'email_mode is "override" but no override recipient is configured';
} else {
  skipReason = 'Email sending is turned off (email_mode = off)';
}

return [{
  json: {
    ok: problems.length === 0,
    problems,
    subject,
    body,
    ai_model: model,
    ai_input_tokens: response.usageMetadata?.promptTokenCount ?? null,
    ai_output_tokens: response.usageMetadata?.candidatesTokenCount ?? null,
    email: {
      should_send: problems.length === 0 && Boolean(recipient),
      recipient,
      mode,
      skip_reason: skipReason,
    },
  },
}];

// Build Success Result
// Reached from three places: "Send Email (SMTP)" success output, its error
// output, or "Send Email?" when sending is skipped. The summary itself was
// generated and validated either way, so the result is Success; email
// delivery is reported separately because email is the optional (bonus) leg.
// Bubble writes this object straight into the NotificationLog.

const request = $('Validate Request').first().json;
const ai = $('Validate AI Output').first().json;
const item = $input.first().json;

const errorText = (err) => {
  if (!err) return '';
  if (typeof err === 'string') return err;
  return err.message || err.description || JSON.stringify(err);
};

let emailDelivery = 'Skipped';
let emailNote = ai.email.skip_reason;
let errorStage = '';
let errorMessage = '';

if ($prevNode.name === 'Send Email (SMTP)') {
  if (item.error) {
    emailDelivery = 'Failed';
    emailNote = '';
    errorStage = 'email_delivery';
    errorMessage = `Summary generated, but email delivery failed: ${errorText(item.error)}`.slice(0, 1000);
  } else {
    emailDelivery = 'Sent';
    emailNote = ai.email.mode === 'override' ? 'Sent to the test inbox (email_mode = override) instead of the author\'s address' : '';
  }
}

return [{
  json: {
    response_code: 200,
    log_id: request.log_id,
    status: 'Success',
    email_subject: ai.subject,
    email_body: ai.body,
    email_delivery: emailDelivery,
    email_recipient: emailDelivery === 'Skipped' ? '' : ai.email.recipient,
    email_note: emailNote,
    error_stage: errorStage,
    error_message: errorMessage,
    ai_model: ai.ai_model,
    ai_input_tokens: ai.ai_input_tokens,
    ai_output_tokens: ai.ai_output_tokens,
    completed_at: new Date().toISOString(),
    n8n_execution_id: String($execution.id),
  },
}];

// Build Failure Result
// Single sink for every error branch after validation. Works out which step
// failed from the node that fed it, so the admin sees "AI generation failed:
// 429 Too Many Requests" rather than a bare "Failed". Returned with HTTP 200:
// the call to n8n worked, the business outcome is what failed, and Bubble
// reads the same fields from every 200 response.

const request = $('Validate Request').first().json;
const item = $input.first().json;

const STAGES = {
  'Build Royalty Facts': { stage: 'build_facts', label: 'Royalty data could not be prepared' },
  'Build AI Request': { stage: 'build_prompt', label: 'The AI request could not be built' },
  'Generate Email (Gemini)': { stage: 'ai_generation', label: 'AI generation failed' },
  'AI Output OK?': { stage: 'ai_output_validation', label: 'AI output failed validation' },
};

let source = '';
try {
  source = $prevNode.name;
} catch {
  source = '';
}
const known = STAGES[source] ?? { stage: 'unknown', label: `Step "${source || 'unknown'}" failed` };

const errorText = (err) => {
  if (!err) return '';
  if (typeof err === 'string') return err;
  const code = err.httpCode ?? err.status ?? '';
  const message = err.message || err.description || JSON.stringify(err);
  return code && !String(message).includes(String(code)) ? `${code} ${message}` : message;
};

const detail = Array.isArray(item.problems) && item.problems.length
  ? item.problems.join('; ')
  : errorText(item.error) || 'No error detail returned';

return [{
  json: {
    response_code: 200,
    log_id: request.log_id,
    status: 'Failed',
    email_subject: '',
    email_body: '',
    email_delivery: 'Not attempted',
    email_recipient: '',
    email_note: '',
    error_stage: known.stage,
    error_message: `${known.label}: ${detail}`.slice(0, 1000),
    ai_model: '',
    ai_input_tokens: null,
    ai_output_tokens: null,
    completed_at: new Date().toISOString(),
    n8n_execution_id: String($execution.id),
  },
}];
